  peek(offset = 1) {
    const p = this.pos + offset;
    if (p >= this.source.length) return '';
    return this.source[p];
  }

  advance() {
    const ch = this.current();
    if (ch === '\n') {
      this.line++;
      this.col = 1;
    } else {
      this.col++;
    }
    this.pos++;
  }

  isAlpha(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_';
  }

