    if (this.current() === '/' && this.peek() === '/') {
      while (this.current() && this.current() !== '\n') {
        this.advance();
      }
    }
  }

  isKeyword(word) {
    const keywords = ['fn', 'let', 'if', 'else', 'while', 'return', 'for', 'break', 'continue', 'true', 'false', 'print', 'println'];
    return keywords.includes(word);
  }

