// ─────────────────────────────────────────────────────────────────
// Level 6: Self-hosted x86-64 ASM Generator for FreeLang
// ─────────────────────────────────────────────────────────────────
//
// 목표: IR → x86-64 NASM 어셈블리 변환
// 전략: 자체호스팅 컴파일러 핵심 (Type Erasure)
//

// ─────────────────────────────────────────────────────────────────
// 1. ASM Generator 상태 관리
// ─────────────────────────────────────────────────────────────────

fn createAsmGenerator() {
  let gen = {};
  gen.lines = [];
  gen.stackDepth = 0;
  gen.varMap = {};
  gen.labelCount = 0;
  return gen;
}

fn asmEmit(gen, line) {
  arr_push(gen.lines, line);
  return gen;
}

fn asmEmitLabel(gen, label) {
  arr_push(gen.lines, label + ":");
  return gen;
}

fn asmEmitComment(gen, text) {
  arr_push(gen.lines, "; " + text);
  return gen;
}

// ─────────────────────────────────────────────────────────────────
// 2. 기본 ASM 연산 (Stack-based)
// ─────────────────────────────────────────────────────────────────

fn asmPush(gen, val) {
  let valStr = str(val);
  asmEmit(gen, "    mov rax, " + valStr);
  asmEmit(gen, "    push rax");
  gen.stackDepth = gen.stackDepth + 1;
  return gen;
}

fn asmPop(gen, reg) {
  asmEmit(gen, "    pop " + reg);
  gen.stackDepth = gen.stackDepth - 1;
  return gen;
}

fn asmAdd(gen) {
  asmEmit(gen, "    pop rbx");
  asmEmit(gen, "    pop rax");
  asmEmit(gen, "    add rax, rbx");
  asmEmit(gen, "    push rax");
  return gen;
}

fn asmSub(gen) {
  asmEmit(gen, "    pop rbx");
  asmEmit(gen, "    pop rax");
  asmEmit(gen, "    sub rax, rbx");
  asmEmit(gen, "    push rax");
  return gen;
}

fn asmMul(gen) {
  asmEmit(gen, "    pop rbx");
  asmEmit(gen, "    pop rax");
  asmEmit(gen, "    imul rax, rbx");
  asmEmit(gen, "    push rax");
  return gen;
}

fn asmDiv(gen) {
  asmEmit(gen, "    pop rbx");
  asmEmit(gen, "    pop rax");
  asmEmit(gen, "    xor edx, edx");
  asmEmit(gen, "    idiv rbx");
  asmEmit(gen, "    push rax");
  return gen;
}

fn asmMod(gen) {
  asmEmit(gen, "    pop rbx");
  asmEmit(gen, "    pop rax");
  asmEmit(gen, "    xor edx, edx");
  asmEmit(gen, "    idiv rbx");
  asmEmit(gen, "    mov rax, rdx");
  asmEmit(gen, "    push rax");
  return gen;
}

// ─────────────────────────────────────────────────────────────────
// 3. 비교 연산
// ─────────────────────────────────────────────────────────────────

/**
 * FreeLang Self-Hosting C Code Generator (Pure v2 Implementation)
 *
 * 자체호스팅 C 코드 생성기 - IR 명령어 배열을 C 코드로 변환
 *
 * ⚠️ 제약사항:
 *   - struct 선언 금지 (객체 리터럴만 사용)
 *   - JS 메서드 금지 (.length, .push 등)
 *   - v2 stdlib 함수만 사용 (arr_push, map_set, string_length 등)
 *
 * 기능:
 *   - IR 명령어 (PUSH, POP, ADD, SUB, MUL, DIV 등) → C 코드 변환
 *   - 스택 기반 실행 환경 (double stack[10240], int sp)
 *   - 변수 맵 관리 (varName → vars[idx])
 *   - 레이블 관리 (JMP, JMP_NOT)
 *   - 함수 호출 지원 (println 등)
 *
 * 생성 출력:
 *   #include <stdio.h>
 *   #include <stdlib.h>
 *   double stack[10240];
 *   int sp = 0;
 *   double vars[256];
 *   int main() { ... }
 *
 * 예시:
 *   let insts = [
 *     {op: "PUSH", arg: 10},
 *     {op: "PUSH", arg: 20},
 *     {op: "ADD"},
 *     {op: "CALL", arg: "println"}
 *   ]
 *   let code = generateCCode(insts)
 *   // #include <stdio.h> ... stack[sp++] = 10; ... printf(...)
 */

// ============================================
// 1. C Code Generator 상태 객체
// ============================================

/**
 * C Code Generator 초기화
 * {
 *   lines: [],        // 생성된 C 코드 라인 배열
 *   varMap: {},       // 변수명 → 인덱스 맵
 *   varIdx: 0,        // 현재 변수 인덱스
 *   labelCount: 0,    // 라벨 카운터
 *   indentLevel: 0    // 들여쓰기 레벨
 * }
 */
fn createCGenerator() {
  return {
    lines: [],
    varMap: {},
    varIdx: 0,
    labelCount: 0,
    indentLevel: 0
  }
}

// ============================================
// 2. 헬퍼 함수 - 라인 추가
// ============================================

/**
 * 코드 라인 추가
 * 들여쓰기 자동 적용
 */
fn emitLine(cgen, line) {
  let indent = ""
  let i = 0
  while (i < cgen.indentLevel) {
    indent = indent + "  "
    i = i + 1
  }
  arr_push(cgen.lines, indent + line)
}

/**
 * 빈 줄 추가
 */
fn emitBlank(cgen) {
  arr_push(cgen.lines, "")
}

/**
 * 들여쓰기 증가
 */
fn increaseIndent(cgen) {
  cgen.indentLevel = cgen.indentLevel + 1
}

/**
 * 들여쓰기 감소
 */
fn decreaseIndent(cgen) {
  cgen.indentLevel = cgen.indentLevel - 1
}

// ============================================

