  console.log(`      Magic: ${Array.from(elfBinary.slice(0, 4)).map(b => '0x' + b.toString(16).padStart(2, '0')).join(' ')}`);

  // Write output
  const outputPath = '/tmp/verify/freelang-final/hello-compiled.elf';
