#!/usr/bin/env node

/**
 * FreeLang Self-Hosting E2E Compiler
 * Lexer → Parser → IR → x86 Encoder → ELF Builder
 *
 * Purpose: Complete end-to-end compilation of hello.free to hello.elf
 * Status: Actual execution, not documentation
 */

const fs = require('fs');
const path = require('path');

// ===== STAGE 1: LEXER (이미 검증됨) =====
class Lexer {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.col = 1;
    this.tokens = [];
  }

  isAlpha(ch) {
    return /[a-zA-Z_]/.test(ch);
  }

  isDigit(ch) {
    return /[0-9]/.test(ch);
  }

  isAlphaNum(ch) {
    return this.isAlpha(ch) || this.isDigit(ch);
  }

  current() {
    return this.source[this.pos] || '\0';
  }

  peek(offset = 1) {
    return this.source[this.pos + offset] || '\0';
  }

  advance() {
    if (this.current() === '\n') {
      this.line++;
      this.col = 1;
    } else {
      this.col++;
    }
    this.pos++;
  }

  skipWhitespace() {
    while (/\s/.test(this.current())) {
      this.advance();
    }
  }

  scanString() {
    const start = this.pos;
    const startCol = this.col;
    this.advance(); // skip opening "
    let value = '';
    while (this.current() !== '"' && this.current() !== '\0') {
      if (this.current() === '\\') {
        this.advance();
        const escaped = this.current();
        if (escaped === 'n') value += '\n';
        else if (escaped === 't') value += '\t';
        else if (escaped === '\\') value += '\\';
        else if (escaped === '"') value += '"';
        else value += escaped;
        this.advance();
      } else {
        value += this.current();
        this.advance();
      }
    }
    if (this.current() === '"') this.advance();
    return { type: 'STRING', value, line: this.line, col: startCol };
  }

  scanNumber() {
    const startCol = this.col;
    let value = '';
    while (this.isDigit(this.current())) {
      value += this.current();
      this.advance();
    }
    if (this.current() === '.' && this.isDigit(this.peek())) {
      value += '.';
      this.advance();
      while (this.isDigit(this.current())) {
        value += this.current();
        this.advance();
      }
    }
    return { type: 'NUMBER', value, line: this.line, col: startCol };
  }

