  println("Welcome to FreeLang HTTP Server");
  return 0;
}

fn body_hello() {
  println("Hello World");
  return 0;
}

fn body_api() {
  println("FreeLang v1.0");
  return 0;
}

fn route_get_root() {
  response_200();
  header_content_type();
  header_content_length(32);
  blank_line();
  body_home();
  return 200;
}

fn route_get_hello() {
  response_200();
  header_content_type();
  header_content_length(11);
  blank_line();
  body_hello();
  return 200;
}

fn route_get_api() {
  response_200();
  header_content_type();
  header_content_length(13);
  blank_line();
  body_api();
  return 200;
}

fn test_http_1() {
  println("Test 1: GET / (200 OK)");
  route_get_root();
  println("");
  return 200;
}

